type AnyRow = Record<string, any>;
type Mode = "dashboard" | "reports" | "objectives";
type Tab = "pilotage" | "analyses" | "alerts";
type Column = { key: string; label: string; value: (row: AnyRow) => ReactNode; raw: (row: AnyRow) => unknown; width?: string };

const supabase = createClient();
const euro = (value: unknown) => new Intl.NumberFormat("fr-FR", { style: "currency", currency: "EUR", maximumFractionDigits: 0 }).format(Number(value || 0));
const percent = (value: unknown) => `${new Intl.NumberFormat("fr-FR", { maximumFractionDigits: 1 }).format(Number(value || 0))} %`;
const date = (value: unknown) => value ? new Intl.DateTimeFormat("fr-FR").format(new Date(`${String(value).slice(0, 10)}T12:00:00`)) : "—";
const month = (value: unknown) => value ? new Intl.DateTimeFormat("fr-FR", { month: "short", year: "2-digit" }).format(new Date(`${String(value).slice(0, 10)}T12:00:00`)) : "—";
const text = (value: unknown) => String(value ?? "").trim();

const config: Record<Mode, { title: string; subtitle: string; singular: string }> = {
  dashboard: { title: "Tableau de bord exécutif", subtitle: "Arbitrez la trajectoire de l’entreprise à partir des données consolidées de tous les modules.", singular: "indicateur" },
  reports: { title: "Rapports & tableaux de bord", subtitle: "Préparez, validez et historisez les revues de management avec leur fiabilité et leurs décisions.", singular: "rapport" },
  objectives: { title: "Objectifs stratégiques", subtitle: "Déclinez la stratégie en objectifs mesurables, responsables, datés et reliés aux données opérationnelles.", singular: "objectif" },
};

function statusTone(value: unknown) {
  const key = text(value).toLowerCase();
  if (["completed", "approved", "published", "closed"].includes(key)) return "completed";
  if (["in_progress", "review"].includes(key)) return "in_progress";
  if (["blocked", "rejected", "late"].includes(key)) return "blocked";
  if (["cancelled", "archived"].includes(key)) return "archived";
  return "planned";
}

function ObjectiveHistoryChart({ objectives, measurements }: { objectives: AnyRow[]; measurements: AnyRow[] }) {
  const objectiveMap = new Map(objectives.map((row) => [String(row.id), row]));
  const monthly = new Map<string, AnyRow>();
  measurements.forEach((measurement) => {
    const objective = objectiveMap.get(String(measurement.objective_id));
    if (!objective) return;
    const key = String(measurement.measured_on || "").slice(0, 7);
    if (!key) return;
    const item = monthly.get(key) || { key, mois: month(`${key}-01`) };
    item[objective.code] = Number(measurement.measured_value || 0);
    monthly.set(key, item);
  });
  const data = [...monthly.values()].sort((left, right) => left.key.localeCompare(right.key));
  const colors = ["#4f46e5", "#0ea5e9", "#10b981", "#f59e0b", "#fb7185", "#8b5cf6", "#14b8a6", "#64748b"];
  const series = objectives.slice(0, 8).map((row, index) => ({ key: row.code, label: row.title, color: colors[index] }));
  return <HrChartCard title="Trajectoire mensuelle des objectifs" description="Historique des mesures consolidées, utile pour distinguer une progression durable d’une valeur ponctuelle." exportConfig={{ type: "line", data, nameKey: "mois", series }}><ResponsiveContainer width="100%" height="100%"><LineChart data={data}><CartesianGrid strokeDasharray="3 3" /><XAxis dataKey="mois" interval={0} /><YAxis /><Tooltip /><Legend />{series.map((item) => <Line key={item.key} dataKey={item.key} name={item.label} stroke={item.color} strokeWidth={2.5} connectNulls dot={{ r: 3 }} />)}</LineChart></ResponsiveContainer></HrChartCard>;
}

function priorityLabel(value: unknown) { return ({ low: "Faible", medium: "Moyenne", high: "Haute" } as Record<string, string>)[text(value)] || "Moyenne"; }
function progress(row: AnyRow) {
  const baseline = Number(row.baseline_value || 0); const current = Number(row.current_value || 0); const target = Number(row.target_value || 0); const delta = target - baseline;
  if (!delta) return current >= target ? 100 : 0;
  return Math.max(0, Math.min(100, ((current - baseline) / delta) * 100));
}

async function resolveOrganization(orgId: string) {
  const request = (supabase.from("organizations" as never) as any).select("id,name,slug");
  const result = /^[0-9a-f-]{36}$/i.test(orgId) ? await request.eq("id", orgId).maybeSingle() : await request.eq("slug", orgId).maybeSingle();
  if (result.error) throw new Error(result.error.message);
  if (!result.data?.id) throw new Error("Organisation introuvable.");
  return result.data as AnyRow;
}

async function loadPilotage(orgId: string) {
  const organization = await resolveOrganization(orgId);
  const read = async (table: string, options: { archived?: boolean; order?: string } = {}) => {
    const base = () => (supabase.from(table as never) as any).select("*").eq("organization_id", organization.id);
    let result = options.archived === false ? await base().limit(1500) : await base().is("archived_at", null).limit(1500);
    // Compatibilité avec les schémas historiques qui ne possèdent pas encore
    // archived_at : on conserve impérativement le filtre tenant puis on trie ici.
    if (result.error && options.archived !== false) result = await base().limit(1500);
    const rows: AnyRow[] = result.error ? [] : (result.data || []);
    return options.order ? rows.sort((left, right) => String(right[options.order!] || "").localeCompare(String(left[options.order!] || ""), "fr", { numeric: true })) : rows;
  };
  const [objectives, reports, objectiveMeasurements, projects, financials, risks, nonconformities, deliverables, prospects, staffing, actions, employees, absences, audits, satisfaction, offers, orders] = await Promise.all([
    read("pilotage_objectives", { order: "target_date" }), read("pilotage_reports", { order: "period_end" }),
    read("pilotage_objective_measurements", { archived: false, order: "measured_on" }),
    read("project_projects", { order: "code" }), read("project_financial_periods", { order: "period_start" }),
    read("project_risks", { order: "review_date" }), read("project_nonconformities", { order: "due_date" }),
    read("project_deliverables", { order: "planned_date" }), read("prospects", { archived: false, order: "created_at" }),
    read("project_staffing_project_overview", { archived: false }), read("project_actions", { order: "due_date" }),
    read("hr_employees", { archived: false }), read("hr_absence_requests", { archived: false }),
    read("project_audits", { order: "audit_date" }), read("project_satisfaction_surveys", { order: "survey_month" }),
    read("offres", { archived: false }), read("commandes", { archived: false }),
  ]);
  return { organization, objectives, reports, objectiveMeasurements, projects, financials, risks, nonconformities, deliverables, prospects, staffing, actions, employees, absences, audits, satisfaction, offers, orders };
}

const emptyObjective = { title: "", description: "", strategic_axis: "performance", status: "open", priority: "medium", owner_name: "", start_date: "", target_date: "", baseline_value: "0", current_value: "0", target_value: "100", unit: "%", confidence_percent: "60", management_comment: "" };
const emptyReport = { title: "", report_type: "executive", frequency: "monthly", status: "planned", owner_name: "", period_start: "", period_end: "", reliability_percent: "60", executive_summary: "", decisions: "", recommended_actions: "" };

