  const [columnFilters, setColumnFilters] = useState<Record<string, string[]>>({}); const [selected, setSelected] = useState<AnyRow | null>(null); const [editing, setEditing] = useState<AnyRow | null>(null); const [formOpen, setFormOpen] = useState(false);
  const [form, setForm] = useState<AnyRow>(mode === "reports" ? emptyReport : emptyObjective); const tableRef = useRef<HTMLElement | null>(null);
