    const production = data.financials.reduce((sum: number, row: AnyRow) => sum + Number(row.production_amount || 0), 0);
    const cost = data.financials.reduce((sum: number, row: AnyRow) => sum + Number(row.actual_cost || 0), 0);
    const margin = production ? (production - cost) / production * 100 : 0;
    const criticalRisks = data.risks.filter((row: AnyRow) => Number(row.inherent_score || Number(row.probability || 0) * Number(row.impact || 0)) >= 12 && !["closed", "completed"].includes(row.status)).length;
    const lateDeliverables = data.deliverables.filter((row: AnyRow) => !["accepted", "cancelled", "delivered"].includes(row.status) && String(row.replanned_date || row.planned_date || "") < today).length;
