    const satisfaction = data.satisfaction.length ? data.satisfaction.reduce((sum: number, row: AnyRow) => sum + Number(row.overall_score || row.global_score || row.average_score || 0), 0) / data.satisfaction.length : 0;
    const row = (code: string, title: string, axis: string, value: number, target: number, unit: string, owner: string, confidence: number, status: string, comment: string) => ({ id: code, code, title, strategic_axis: axis, metric_value: value, current_value: value, baseline_value: 0, target_value: target, unit, owner_name: owner, confidence_percent: confidence, status, priority: status === "blocked" ? "high" : status === "in_progress" ? "medium" : "low", target_date: `${new Date().getFullYear()}-12-31`, management_comment: comment });
